'use client'

import type {
  Column,
  ColumnDataType,
  DataTableFilterActions,
  FilterModel,
  FilterStrategy,
  FiltersState,
  Locale,
} from '@bazza-ui/filters'
import { getColumn, isAnyOf, t } from '@bazza-ui/filters'
import { ArrowRightIcon, ChevronRightIcon } from 'lucide-react'
import React, {
  isValidElement,
  memo,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { cn } from '@/lib/utils'
import { useFilterContext } from '../../../components/root/filter-context'
import { FilterTrigger } from '../../../components/trigger/filter-trigger'
import { FilterValueController } from '../item/filter-value'

export interface FilterMenuProps<TData = unknown> {
  columns?: Column<TData>[]
  filters?: FiltersState
  actions?: DataTableFilterActions
  strategy?: FilterStrategy
  locale?: Locale
  children?: React.ReactElement
  rootProps?: Partial<Omit<React.ComponentProps<typeof Popover>, 'children'>>
}

function __FilterMenu<TData>({
  columns: columnsProp,
  filters: filtersProp,
  actions: actionsProp,
  strategy: strategyProp,
  locale: localeProp,
  children,
  rootProps,
}: FilterMenuProps<TData>) {
  const context = useFilterContext<TData>()

  const columns = columnsProp ?? context.columns
  const filters = filtersProp ?? context.filters
  const actions = actionsProp ?? context.actions
  const strategy = strategyProp ?? context.strategy
  const locale = localeProp ?? context.locale ?? 'en'

  const visibleColumns = useMemo(
    () => columns.filter((column) => !column.hidden),
    [columns],
  )

  const visibleFilters = useMemo(
    () =>
      filters.filter((filter) =>
        visibleColumns.find((column) => column.id === filter.columnId),
      ),
    [filters, visibleColumns],
  )

  const hasVisibleFilters = visibleFilters.length > 0

  const [value, setValue] = useState('')
  const [property, setProperty] = useState<string | undefined>(undefined)
  const inputRef = useRef<HTMLInputElement>(null)

  const {
    open: openProp,
    onOpenChange: onOpenChangeProp,
    ...restRootProps
  } = rootProps ?? {}

  const [internalOpen, setInternalOpen] = useState(false)
  const open = openProp ?? internalOpen

  const selectedColumn = property
    ? getColumn(visibleColumns, property)
    : undefined
  const selectedFilter = property
    ? visibleFilters.find((filter) => filter.columnId === property)
    : undefined

  useEffect(() => {
    if (!property) {
      return
    }

    inputRef.current?.focus()
    setValue('')
  }, [property])

  const handleOpenChange = useCallback(
    (nextOpen: boolean) => {
      if (openProp === undefined) {
        setInternalOpen(nextOpen)
      }

      onOpenChangeProp?.(nextOpen)

      if (!nextOpen) {
        setTimeout(() => {
          setProperty(undefined)
        }, 100)

        setTimeout(() => {
          setValue('')
        }, 150)
      }
    },
    [openProp, onOpenChangeProp],
  )

  const content = useMemo(() => {
    if (property && selectedColumn && selectedColumn.type !== 'boolean') {
      return (
        <FilterValueController
          filter={selectedFilter as FilterModel<ColumnDataType> | undefined}
          column={selectedColumn as Column<TData, ColumnDataType>}
          actions={actions}
          strategy={strategy}
          locale={locale}
        />
      )
    }

    return (
      <Command
        loop
        filter={(itemValue, search, keywords) => {
          const extendedValue = `${itemValue} ${keywords?.join(' ')}`

          return extendedValue.toLowerCase().includes(search.toLowerCase())
            ? 1
            : 0
        }}
      >
        <CommandInput
          value={value}
          onValueChange={setValue}
          ref={inputRef}
          placeholder={t('search', locale)}
        />

        <CommandEmpty>{t('noresults', locale)}</CommandEmpty>

        <CommandList className="max-h-fit">
          <CommandGroup>
            {visibleColumns.map((column) => (
              <FilterableColumn
                key={column.id}
                column={column}
                setProperty={setProperty}
                actions={actions}
              />
            ))}

            <QuickSearchFilters
              search={value}
              filters={visibleFilters}
              columns={visibleColumns}
              actions={actions}
            />
          </CommandGroup>
        </CommandList>
      </Command>
    )
  }, [
    property,
    selectedColumn,
    selectedFilter,
    actions,
    locale,
    strategy,
    value,
    visibleColumns,
    visibleFilters,
  ])

  const triggerElement = children ?? (
    <FilterTrigger hasVisibleFilters={hasVisibleFilters} locale={locale} />
  )

  return (
    <Popover open={open} onOpenChange={handleOpenChange} {...restRootProps}>
      <PopoverTrigger asChild>{triggerElement}</PopoverTrigger>
      <PopoverContent
        align="start"
        side="bottom"
        className="w-fit p-0 origin-(--radix-popover-content-transform-origin)"
      >
        {content}
      </PopoverContent>
    </Popover>
  )
}

interface FilterableColumnProps<
  TData,
  TType extends ColumnDataType = ColumnDataType,
> {
  column: Column<TData, TType>
  setProperty: (value: string) => void
  actions: DataTableFilterActions
}

function FilterableColumn<TData, TType extends ColumnDataType>({
  column,
  setProperty,
  actions,
}: FilterableColumnProps<TData, TType>) {
  const itemRef = useRef<HTMLDivElement>(null)

  const { icon: Icon } = column
  const hasIcon = !!Icon

  const prefetch = useCallback(() => {
    column.prefetchValues()

    if (isAnyOf(column.type, ['option', 'multiOption'])) {
      column.prefetchOptions()
      column.prefetchFacetedUniqueValues()
    }

    if (column.type === 'number') {
      column.prefetchFacetedMinMaxValues()
    }
  }, [column])

  useEffect(() => {
    const target = itemRef.current

    if (!target) {
      return
    }

    const observer = new MutationObserver(() => {
      const isSelected = target.getAttribute('data-selected') === 'true'

      if (isSelected) {
        prefetch()
      }
    })

    observer.observe(target, {
      attributes: true,
      attributeFilter: ['data-selected'],
    })

    return () => {
      observer.disconnect()
    }
  }, [prefetch])

  function handleSelect() {
    if (column.type === 'boolean') {
      actions.setFilterValue(column as Column<TData, 'boolean'>, [true])
      return
    }

    setProperty(column.id)
  }

  return (
    <CommandItem
      ref={itemRef}
      value={column.id}
      keywords={[column.displayName]}
      onSelect={handleSelect}
      className="group"
      onMouseEnter={prefetch}
    >
      <div className="flex w-full items-center justify-between">
        <div className="inline-flex items-center gap-1.5">
          {hasIcon &&
            (isValidElement(Icon) ? (
              Icon
            ) : (
              <Icon className="size-4 stroke-[2.25px]" />
            ))}

          <span>{column.displayName}</span>
        </div>

        {column.type !== 'boolean' && (
          <ArrowRightIcon className="size-4 opacity-0 group-aria-selected:opacity-100" />
        )}
      </div>
    </CommandItem>
  )
}

interface QuickSearchFiltersProps<TData> {
  search?: string
  filters: FiltersState
  columns: Column<TData>[]
  actions: DataTableFilterActions
}

const QuickSearchFilters = memo(function QuickSearchFilters<TData>({
  search,
  filters,
  columns,
  actions,
}: QuickSearchFiltersProps<TData>) {
  const selectableColumns = useMemo(
    () =>
      columns.filter((column) =>
        isAnyOf<ColumnDataType>(column.type, ['option', 'multiOption']),
      ),
    [columns],
  )

  if (!search || search.trim().length < 2) {
    return null
  }

  return (
    <>
      {selectableColumns.map((column) => {
        const filter = filters.find(
          (currentFilter) => currentFilter.columnId === column.id,
        )
        const options = column.getOptions()
        const optionsCount = column.getFacetedUniqueValues()

        function handleOptionSelect(value: string, checked: boolean) {
          if (checked) {
            actions.addFilterValue(column as Column<TData, 'option'>, [value])
            return
          }

          actions.removeFilterValue(column as Column<TData, 'option'>, [value])
        }

        return (
          <React.Fragment key={column.id}>
            {options.map((option) => {
              const checked = Boolean(filter?.values.includes(option.value))
              const count = optionsCount?.get(option.value as string) ?? 0

              return (
                <CommandItem
                  key={`${column.id}-${option.value}`}
                  value={`${column.id}-${option.value}`}
                  keywords={[
                    option.label,
                    option.value as string,
                    column.displayName,
                  ]}
                  onSelect={() => {
                    handleOptionSelect(option.value as string, !checked)
                  }}
                  className="group"
                >
                  <div className="flex items-center gap-1.5 group">
                    <Checkbox
                      checked={checked}
                      className="opacity-0 data-[state=checked]:opacity-100 group-data-[selected=true]:opacity-100 dark:border-ring mr-1"
                    />

                    <div className="flex items-center w-4 justify-center">
                      {option.icon &&
                        (isValidElement(option.icon) ? (
                          option.icon
                        ) : (
                          <option.icon className="size-4 text-primary" />
                        ))}
                    </div>

                    <div className="flex items-center gap-0.5">
                      <span className="text-muted-foreground">
                        {column.displayName}
                      </span>
                      <ChevronRightIcon className="size-3.5 text-muted-foreground/75" />
                      <span>
                        {option.label}
                        <sup
                          className={cn(
                            !optionsCount && 'hidden',
                            'ml-0.5 tabular-nums tracking-tight text-muted-foreground',
                            count === 0 && 'slashed-zero',
                          )}
                        >
                          {count < 100 ? count : '100+'}
                        </sup>
                      </span>
                    </div>
                  </div>
                </CommandItem>
              )
            })}
          </React.Fragment>
        )
      })}
    </>
  )
}) as <TData>(
  props: QuickSearchFiltersProps<TData>,
) => React.ReactElement | null

export const FilterMenu = memo(__FilterMenu) as typeof __FilterMenu

export namespace FilterMenu {
  export type Props<TData = unknown> = FilterMenuProps<TData>
}

'use client'

import {
  booleanFilterOperators,
  type Column,
  type ColumnDataType,
  type DataTableFilterActions,
  dateFilterOperators,
  type FilterModel,
  filterTypeOperatorDetails,
  isBooleanColumn,
  isDateColumn,
  isMultiOptionColumn,
  isNumberColumn,
  isOptionColumn,
  isTextColumn,
  type Locale,
  multiOptionFilterOperators,
  numberFilterOperators,
  optionFilterOperators,
  t,
  textFilterOperators,
} from '@bazza-ui/filters'
import { type ComponentPropsWithoutRef, forwardRef, useState } from 'react'
import { Button } from '@/components/ui/button'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { cn } from '@/lib/utils'
import { useFilterItemContext } from '../../../components/item/filter-item'
import {
  useFilterActions,
  useFilterLocale,
} from '../../../components/root/filter-context'

export interface FilterOperatorProps<
  TData = unknown,
  TType extends ColumnDataType = ColumnDataType,
> extends Omit<ComponentPropsWithoutRef<typeof Button>, 'onClick' | 'variant'> {
  column?: Column<TData, TType>
  filter?: FilterModel<TType>
  actions?: DataTableFilterActions
  locale?: Locale
}

function getOperators<TData, TType extends ColumnDataType>(
  column: Column<TData, TType>,
) {
  if (isTextColumn(column)) return textFilterOperators
  if (isOptionColumn(column)) return optionFilterOperators
  if (isMultiOptionColumn(column)) return multiOptionFilterOperators
  if (isDateColumn(column)) return dateFilterOperators
  if (isNumberColumn(column)) return numberFilterOperators
  if (isBooleanColumn(column)) return booleanFilterOperators
  return {}
}

/**
 * Displays and allows changing the filter operator (e.g., "is", "contains").
 * Renders a `<button>` element with a popover + cmdk list.
 */
export const FilterOperator = forwardRef<
  HTMLButtonElement,
  FilterOperatorProps
>(
  (
    {
      column: columnProp,
      filter: filterProp,
      actions: actionsProp,
      locale: localeProp,
      className,
      ...props
    },
    ref,
  ) => {
    const itemContext = useFilterItemContext()
    const filterActions = useFilterActions()
    const filterLocale = useFilterLocale()

    const column = columnProp ?? itemContext?.column
    const filter = filterProp ?? itemContext?.filter
    const actions = actionsProp ?? itemContext?.actions ?? filterActions
    const locale = localeProp ?? itemContext?.locale ?? filterLocale ?? 'en'

    const [open, setOpen] = useState(false)

    if (!column || !filter || !actions) {
      throw new Error(
        'FilterOperator requires column, filter, and actions props or must be used within FilterItem',
      )
    }

    const operators = getOperators(column) as Record<
      string,
      {
        key: string
        value: string
        target: string
        isNegated?: boolean
        negation?: string
        negationOf?: string
      }
    >
    const currentOperator = operators[filter.operator]
    const relatedOperators = Object.values(operators).filter(
      (operator) =>
        currentOperator && operator.target === currentOperator.target,
    )

    const operatorDetails = filterTypeOperatorDetails[column.type] as Record<
      string,
      { key: string }
    >
    const operator = operatorDetails[filter.operator]
    const label = operator ? t(operator.key, locale) : filter.operator

    return (
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            ref={ref}
            data-slot="filter-operator"
            data-column-type={column.type}
            data-operator={filter.operator}
            variant="ghost"
            className={cn(
              'm-0 w-fit whitespace-nowrap p-0 px-2 text-xs text-muted-foreground h-full rounded-none',
              className,
            )}
            onClick={(event) => {
              if (!isBooleanColumn(column)) {
                return
              }

              event.preventDefault()

              const details =
                filterTypeOperatorDetails.boolean[
                  filter.operator as 'is' | 'is not'
                ]
              const nextOperator = details.isNegated
                ? details.negationOf
                : details.negation

              if (nextOperator) {
                actions.setFilterOperator(column.id, nextOperator)
              }
            }}
            {...props}
          >
            <span>{label}</span>
          </Button>
        </PopoverTrigger>

        <PopoverContent
          align="start"
          className="w-fit min-w-[170px] p-0 origin-(--radix-popover-content-transform-origin)"
        >
          <Command loop>
            <CommandInput placeholder={t('search', locale)} />
            <CommandEmpty>{t('noresults', locale)}</CommandEmpty>
            <CommandList className="max-h-fit">
              <CommandGroup>
                {relatedOperators.map((relatedOperator) => {
                  const operatorLabel = t(relatedOperator.key, locale)

                  return (
                    <CommandItem
                      key={relatedOperator.value}
                      value={relatedOperator.value}
                      keywords={[operatorLabel]}
                      onSelect={() => {
                        actions.setFilterOperator(
                          column.id,
                          relatedOperator.value as any,
                        )
                        setOpen(false)
                      }}
                    >
                      {operatorLabel}
                    </CommandItem>
                  )
                })}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    )
  },
)

FilterOperator.displayName = 'FilterOperator'

export namespace FilterOperator {
  export type Props<
    TData = unknown,
    TType extends ColumnDataType = ColumnDataType,
  > = FilterOperatorProps<TData, TType>
}

'use client'

import type {
  Column,
  ColumnDataType,
  ColumnOptionExtended,
  DataTableFilterActions,
  FilterModel,
  FilterStrategy,
  Locale,
} from '@bazza-ui/filters'
import {
  isBooleanColumn,
  isBooleanFilter,
  isDateColumn,
  isDateFilter,
  isMultiOptionColumn,
  isMultiOptionFilter,
  isNumberColumn,
  isNumberFilter,
  isOptionColumn,
  isOptionFilter,
  isTextColumn,
  isTextFilter,
  t,
  take,
} from '@bazza-ui/filters'
import { format } from 'date-fns'
import { Ellipsis } from 'lucide-react'
import type * as React from 'react'
import {
  cloneElement,
  forwardRef,
  isValidElement,
  memo,
  useCallback,
  useMemo,
  useRef,
  useState,
} from 'react'
import { Button, buttonVariants } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from '@/components/ui/command'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { cn } from '@/lib/utils'
import { useFilterItemContext } from '../../../components/item/filter-item'
import {
  useFilterActions,
  useFilterEntityName,
  useFilterLocale,
  useFilterStrategy,
} from '../../../components/root/filter-context'
import { FilterValueDateController } from '../../../components/value/filter-value-date-controller'
import { FilterValueNumberController } from '../../../components/value/filter-value-number-controller'
import { DebouncedInput } from '../../../ui/debounced-input'

type ScalarValue = string | number | bigint | boolean | Date

export interface FilterValueProps<
  TData = unknown,
  TType extends ColumnDataType = ColumnDataType,
> {
  filter?: FilterModel<TType>
  column?: Column<TData, TType>
  actions?: DataTableFilterActions
  strategy?: FilterStrategy
  locale?: Locale
  entityName?: string
  className?: string
}

interface FilterValueControllerInput<TData, TType extends ColumnDataType> {
  filter?: FilterModel<TType>
  column: Column<TData, TType>
  actions: DataTableFilterActions
  strategy: FilterStrategy
  locale?: Locale
  initialValues?: ScalarValue[]
}

/**
 * Displays and allows editing the filter value.
 * Renders a `<button>` element with a popover + cmdk controller.
 */
export const FilterValue = forwardRef<HTMLButtonElement, FilterValueProps>(
  (
    {
      filter: filterProp,
      column: columnProp,
      actions: actionsProp,
      strategy: strategyProp,
      locale: localeProp,
      entityName: entityNameProp,
      className,
    },
    ref,
  ) => {
    const itemContext = useFilterItemContext()
    const filterActions = useFilterActions()
    const filterStrategy = useFilterStrategy()
    const filterLocale = useFilterLocale()
    const filterEntityName = useFilterEntityName()

    const filter = filterProp ?? itemContext?.filter
    const column = columnProp ?? itemContext?.column
    const actions = actionsProp ?? itemContext?.actions ?? filterActions
    const strategy = strategyProp ?? itemContext?.strategy ?? filterStrategy
    const locale = localeProp ?? itemContext?.locale ?? filterLocale ?? 'en'
    const entityName =
      entityNameProp ?? itemContext?.entityName ?? filterEntityName

    if (!filter || !column || !actions || !strategy) {
      throw new Error(
        'FilterValue requires filter, column, actions, and strategy props or must be used within FilterItem',
      )
    }

    const resolvedFilter = filter
    const resolvedColumn = column
    const resolvedActions = actions
    const resolvedStrategy = strategy

    const [open, setOpen] = useState(false)
    const initialFilterValuesRef = useRef<ScalarValue[]>([])

    function handleClick(event: React.MouseEvent<HTMLButtonElement>) {
      if (isBooleanColumn(resolvedColumn)) {
        event.preventDefault()
      }
    }

    if (isBooleanColumn(resolvedColumn)) {
      return (
        <div
          data-slot="filter-value"
          data-column-type={resolvedColumn.type}
          className={cn(
            buttonVariants({ variant: 'ghost' }),
            'm-0 w-fit whitespace-nowrap p-0 px-2 text-xs h-full rounded-none',
            'text-primary/75 hover:bg-inherit hover:text-primary/75 hover:shadow-none',
            className,
          )}
        >
          <FilterValueDisplay
            filter={resolvedFilter}
            column={resolvedColumn}
            locale={locale}
            entityName={entityName}
          />
        </div>
      )
    }

    return (
      <Popover
        open={open}
        onOpenChange={(nextOpen) => {
          if (nextOpen) {
            initialFilterValuesRef.current = resolvedFilter.values
          }

          setOpen(nextOpen)
        }}
      >
        <PopoverTrigger asChild>
          <Button
            ref={ref}
            data-slot="filter-value"
            data-column-type={resolvedColumn.type}
            variant="ghost"
            className={cn(
              'm-0 w-fit whitespace-nowrap p-0 px-2 text-xs h-full rounded-none',
              className,
            )}
            onClick={handleClick}
          >
            <FilterValueDisplay
              filter={resolvedFilter}
              column={resolvedColumn}
              locale={locale}
              entityName={entityName}
            />
          </Button>
        </PopoverTrigger>

        <PopoverContent
          align="start"
          side="bottom"
          className="w-fit p-0 origin-(--radix-popover-content-transform-origin)"
        >
          <FilterValueController
            filter={resolvedFilter}
            column={resolvedColumn}
            actions={resolvedActions}
            strategy={resolvedStrategy}
            locale={locale}
            initialValues={initialFilterValuesRef.current}
          />
        </PopoverContent>
      </Popover>
    )
  },
)

FilterValue.displayName = 'FilterValue'

export function FilterValueController<TData, TType extends ColumnDataType>({
  filter,
  column,
  actions,
  strategy,
  locale = 'en',
  initialValues = [],
}: FilterValueControllerInput<TData, TType>) {
  switch (column.type) {
    case 'option':
      return (
        <FilterValueOptionController
          filter={filter as FilterModel<'option'> | undefined}
          column={column as Column<TData, 'option'>}
          actions={actions}
          strategy={strategy}
          locale={locale}
          initialValues={initialValues}
        />
      )
    case 'multiOption':
      return (
        <FilterValueMultiOptionController
          filter={filter as FilterModel<'multiOption'> | undefined}
          column={column as Column<TData, 'multiOption'>}
          actions={actions}
          strategy={strategy}
          locale={locale}
          initialValues={initialValues}
        />
      )
    case 'date':
      return (
        <FilterValueDateController
          filter={filter as FilterModel<'date'>}
          column={column as Column<TData, 'date'>}
          actions={actions}
          strategy={strategy}
          locale={locale}
        />
      )
    case 'text':
      return (
        <FilterValueTextController
          filter={filter as FilterModel<'text'> | undefined}
          column={column as Column<TData, 'text'>}
          actions={actions}
          strategy={strategy}
          locale={locale}
        />
      )
    case 'number':
      return (
        <FilterValueNumberController
          filter={filter as FilterModel<'number'>}
          column={column as Column<TData, 'number'>}
          actions={actions}
          strategy={strategy}
          locale={locale}
        />
      )
    default:
      return null
  }
}

interface OptionItemProps {
  option: ColumnOptionExtended & {
    selected: boolean
  }
  onToggle: (value: string, checked: boolean) => void
}

const OptionItem = memo(function OptionItem({
  option,
  onToggle,
}: OptionItemProps) {
  const { value, label, icon: Icon, selected, count } = option

  const handleSelect = useCallback(() => {
    onToggle(value as string, !selected)
  }, [onToggle, value, selected])

  return (
    <CommandItem
      value={`${label} ${String(value)}`}
      keywords={[String(value), String(label)]}
      onSelect={handleSelect}
      className="group flex items-center justify-between gap-4"
    >
      <div className="flex items-center gap-1.5 flex-1 min-w-0">
        <Checkbox
          checked={selected}
          className="opacity-0 data-[state=checked]:opacity-100 group-data-[selected=true]:opacity-100 dark:border-ring mr-1 shrink-0"
        />

        <div className="shrink-0">
          {Icon &&
            (isValidElement(Icon) ? (
              Icon
            ) : (
              <Icon className="size-4 text-primary" />
            ))}
        </div>

        <span className="overflow-ellipsis whitespace-nowrap overflow-x-hidden">
          {label}
        </span>
      </div>

      {count && (
        <span className="tabular-nums text-muted-foreground tracking-tight text-xs">
          {new Intl.NumberFormat().format(count)}
        </span>
      )}
    </CommandItem>
  )
})

interface SelectableControllerProps<
  TData,
  TType extends 'option' | 'multiOption',
> {
  filter?: FilterModel<TType>
  column: Column<TData, TType>
  actions: DataTableFilterActions
  strategy: FilterStrategy
  locale?: Locale
  initialValues?: ScalarValue[]
}

function FilterValueSelectableController<
  TData,
  TType extends 'option' | 'multiOption',
>({
  filter,
  column,
  actions,
  locale = 'en',
  initialValues = [],
}: SelectableControllerProps<TData, TType>) {
  const initialSelectedValuesRef = useRef(
    new Set(
      (initialValues.length > 0
        ? initialValues
        : ((filter?.values as
            | Array<string | number | bigint | boolean>
            | undefined) ?? [])
      ).map((value) => String(value)),
    ),
  )

  const initialSelectedValues = initialSelectedValuesRef.current

  const { selectedOptions, unselectedOptions } = useMemo(() => {
    const counts = column.getFacetedUniqueValues()

    const allOptions = column.getOptions().map((option) => {
      const optionValue = String(option.value)

      return {
        ...option,
        value: optionValue,
        selected: filter?.values.includes(option.value as any) ?? false,
        count: counts?.get(optionValue) ?? 0,
      }
    })

    const selected = allOptions.filter((option) =>
      initialSelectedValues.has(String(option.value)),
    )

    const unselected = allOptions.filter(
      (option) => !initialSelectedValues.has(String(option.value)),
    )

    return {
      selectedOptions: selected,
      unselectedOptions: unselected,
    }
  }, [column, filter?.values, initialSelectedValues])

  const handleToggle = useCallback(
    (value: string, checked: boolean) => {
      if (checked) {
        actions.addFilterValue(column as Column<TData, 'option'>, [value])
        return
      }

      actions.removeFilterValue(column as Column<TData, 'option'>, [value])
    },
    [actions, column],
  )

  return (
    <Command className="max-w-[300px]" loop>
      <CommandInput
        autoFocus
        placeholder={`Search ${column.displayName.toLowerCase()}...`}
      />
      <CommandEmpty>{t('noresults', locale)}</CommandEmpty>

      <CommandList>
        <CommandGroup className={cn(selectedOptions.length === 0 && 'hidden')}>
          {selectedOptions.map((option) => (
            <OptionItem
              key={option.value}
              option={option}
              onToggle={handleToggle}
            />
          ))}
        </CommandGroup>

        <CommandSeparator
          className={cn(
            (unselectedOptions.length === 0 || selectedOptions.length === 0) &&
              'hidden',
          )}
        />

        <CommandGroup
          className={cn(unselectedOptions.length === 0 && 'hidden')}
        >
          {unselectedOptions.map((option) => (
            <OptionItem
              key={option.value}
              option={option}
              onToggle={handleToggle}
            />
          ))}
        </CommandGroup>
      </CommandList>
    </Command>
  )
}

function FilterValueOptionController<TData>({
  filter,
  column,
  actions,
  strategy,
  locale,
  initialValues,
}: SelectableControllerProps<TData, 'option'>) {
